// @pit: {"label": "Probe public sources for long-run S&P 500 and Nasdaq monthly history"}
async ({ http: { request } }) => {
  const urls = [
    "https://stooq.com/q/d/l/?s=^spx&i=m",
    "https://query1.finance.yahoo.com/v8/finance/chart/%5EGSPC?period1=788918400&period2=1794787200&interval=1mo",
    "https://query1.finance.yahoo.com/v8/finance/chart/%5EIXIC?period1=788918400&period2=1794787200&interval=1mo",
    "https://raw.githubusercontent.com/datasets/s-and-p-500/main/data/data.csv",
    "https://fred.stlouisfed.org/graph/fredgraph.csv?id=NASDAQCOM",
  ];
  const r = await Promise.allSettled(urls.map((u) => request(u, { maxBytes: 1_000_000, headers: { "User-Agent": "Mozilla/5.0" } })));
  return r.map((x, i) => x.status === "fulfilled" ? { url: urls[i], status: x.value.status, len: x.value.body.length, head: x.value.body.slice(0, 200), tail: x.value.body.slice(-200) } : { url: urls[i], err: String(x.reason).slice(0, 200) }) as PitJsonValue;
}
